class Solution {
public:
    std::string toHexspeak(std::string num) {
        long long n = std::stoll(num);
        std::stringstream ss;
        ss << std::hex << std::uppercase << n;
        std::string h = ss.str();
        std::string res = "";
        for (char ch : h) {
            if (ch == '0') res += 'O';
            else if (ch == '1') res += 'I';
            else if (ch >= 'A' && ch <= 'F') res += ch;
            else return "ERROR";
        }
        return res;
    }
};

class Solution {
    public String toHexspeak(String num) {
        long n = Long.parseLong(num);
        String h = Long.toHexString(n).toUpperCase();
        StringBuilder res = new StringBuilder();
        for (char ch : h.toCharArray()) {
            if (ch == '0') res.append('O');
            else if (ch == '1') res.append('I');
            else if (ch >= 'A' && ch <= 'F') res.append(ch);
            else return "ERROR";
        }
        return res.toString();
    }
}

var toHexspeak = function(num) {
    const h = BigInt(num).toString(16).toUpperCase();
    let res = '';
    for (const ch of h) {
        if (ch === '0') res += 'O';
        else if (ch === '1') res += 'I';
        else if (ch >= 'A' && ch <= 'F') res += ch;
        else return 'ERROR';
    }
    return res;
};
